<template><section class="procurement-detail">
  <header><div><h2>{{ kind==='purchase'?document.poName:document.noName||'采购到货' }}</h2><p class="code">{{ number }} <el-button v-clipboard:copy="number" type="text" icon="el-icon-document-copy" title="复制单号"/></p></div><el-button size="small" icon="el-icon-refresh" @click="$emit('refresh')">刷新详情</el-button></header>
  <el-alert :title="notice" :type="document.cutoffState?'warning':'info'" :closable="false" show-icon/>
  <div class="metrics"><article v-for="metric in metrics" :key="metric.key"><span>{{ metric.label }}</span><strong>{{ metricText(metric.key) }}</strong></article></div>
  <el-descriptions border :column="3" size="small"><el-descriptions-item label="供应商">{{ document.supplierName || '查看来源采购' }}</el-descriptions-item><el-descriptions-item label="货主 / 实仓">{{ document.ownerName }} / {{ document.realWarehouseName }}</el-descriptions-item><el-descriptions-item label="接收虚仓">{{ document.warehouseName }} · {{ document.wmsSimulationCode }}</el-descriptions-item><el-descriptions-item :label="kind==='purchase'?'预计到货日期':'本批预计到货'">{{ date(kind==='purchase'?document.expectedDate:document.expectedCallbackTime) }}</el-descriptions-item><el-descriptions-item v-if="kind==='purchase'" label="采购计划金额">¥ {{ money(document.moneyExpected) }}</el-descriptions-item><el-descriptions-item v-else label="来源采购">{{ document.poSn }}<el-button v-if="document.purchaseId" type="text" @click="$emit('show','purchase',{id:document.purchaseId})">查看采购</el-button></el-descriptions-item><el-descriptions-item label="备注 / 关闭依据">{{ document.closeReason || document.remarks || '—' }}</el-descriptions-item></el-descriptions>
  <div class="actions"><el-button v-if="can('approve')&&((kind==='purchase'&&document.poState===1&&!document.stateNeedsReview)||(kind==='receipt'&&document.noState===2))" type="primary" size="small" @click="$emit('approve')">{{ kind==='purchase'?'审核采购计划':'审核本批到货' }}</el-button><el-button v-if="kind==='purchase'&&can('receive')&&[2,3].includes(document.poState)" type="primary" size="small" :disabled="!summary.unarranged||document.cutoffState==='PROCESSING'" @click="$emit('receipt')">安排到货</el-button><el-button v-if="can('cutoff')&&active" size="small" @click="$emit('cutoff')">{{ document.cutoffState?'查看截单处理结果':kind==='purchase'?'撤回到货 / 终止剩余采购':'停止本批剩余收货' }}</el-button><el-button v-if="kind==='purchase'&&can('close')&&[2,3].includes(document.poState)" size="small" @click="$emit('close')">关闭剩余采购</el-button><el-button v-if="document.receiptReviewPending" v-hasPermi="['warehouse:poInfo:cutoffReview']" size="small" type="warning" @click="$emit('cutoff')">截单后到货待核对 {{ document.receiptReviewPending }} 条</el-button></div>
  <el-tabs v-model="tab">
    <el-tab-pane label="商品与数量" name="lines"><p class="muted">已安排包含有效在途批次及已入账数量；最终短收批次入账完成后，差额释放为可重新安排数量。仓库实收与库存入账分别计算。</p><el-table :data="document.lines" size="small" class="procurement-lines"><el-table-column label="商品 / SKU" min-width="230"><template slot-scope="{row}"><strong>{{ row.goodsName }}</strong><div class="muted">{{ row.skuSn }}</div></template></el-table-column><el-table-column :label="kind==='purchase'?'采购计划':'本批安排'" width="110"><template slot-scope="{row}">{{ kind==='purchase'?row.quantity:Number(row.zpNumberExpected)+Number(row.cpNumberExpected) }} {{ row.stockUnit }}</template></el-table-column><el-table-column v-if="kind==='purchase'" label="已安排 / 未安排" min-width="150"><template slot-scope="{row}">{{ row.scheduledQuantity }} / {{ row.unarrangedQuantity }} {{ row.stockUnit }}</template></el-table-column><el-table-column label="已确认实收 / 次品" min-width="150"><template slot-scope="{row}">{{ row.confirmedQuantity }} {{ row.stockUnit }}<div class="muted">其中次品 {{ row.badQuantity }} {{ row.stockUnit }}</div></template></el-table-column><el-table-column label="已入账 / 待入账" min-width="150"><template slot-scope="{row}">{{ row.postedQuantity }} {{ row.stockUnit }}<div :class="row.unpostedQuantity?'warning':'muted'">待入账 {{ row.unpostedQuantity }} {{ row.stockUnit }}</div></template></el-table-column><el-table-column label="待收 / 最终短收" min-width="150"><template slot-scope="{row}">待收 {{ row.unreceivedQuantity }} {{ row.stockUnit }}<div class="warning" v-if="row.shortQuantity">最终短收 {{ row.shortQuantity }} {{ row.stockUnit }}</div><div v-if="row.cancelledQuantity" class="muted">已截停 {{ row.cancelledQuantity }} {{ row.stockUnit }}</div></template></el-table-column><el-table-column label="采购单价" width="110"><template slot-scope="{row}">¥ {{ money(row.purchasePrice) }}</template></el-table-column></el-table></el-tab-pane>
    <el-tab-pane v-if="kind==='purchase'" :label="'到货批次（'+(document.receipts||[]).length+'）'" name="receipts" lazy><el-table :data="document.receipts" size="small"><el-table-column label="到货单 / 批次" min-width="280"><template slot-scope="{row}"><el-button type="text" @click="$emit('show','receipt',row)">{{ row.noSn }}</el-button><div class="muted">{{ row.batchCode }}</div></template></el-table-column><el-table-column label="本批安排 / 已入账" min-width="150"><template slot-scope="{row}">{{ row.numberExpected }} / {{ row.numberActually }}<div class="muted">数量单位见本批商品明细</div></template></el-table-column><el-table-column label="预计到货" min-width="140"><template slot-scope="{row}">{{ date(row.expectedCallbackTime) }}</template></el-table-column><el-table-column label="仓库交互" min-width="230"><template slot-scope="{row}"><warehouse-interaction-cell :row="{warehouseExecutions:row.executions||[]}" @open="selectWarehouse"/></template></el-table-column><el-table-column label="状态" min-width="150"><template slot-scope="{row}">{{ receiptStates[row.noState] || '状态待核对' }}</template></el-table-column></el-table></el-tab-pane>
    <el-tab-pane label="实收与入账" name="stock" lazy><div class="toolbar"><span>选择关联入库单</span><el-select v-model="selectedId" size="small"><el-option v-for="t in document.tickets" :key="t.id" :value="Number(t.id)" :label="t.sn"/></el-select></div><template v-if="selected"><ticket-summary :document="selected"/><wms-inbound-panel v-if="selected.actualWarehouse===1" compact :ticket-id="Number(selected.id)" @changed="$emit('refresh')"/><div class="actions"><el-button v-if="selected.actualWarehouse===2&&canRetry&&selected.inventoryStatus!==2" size="small" @click="$emit('retry',selected)">继续虚拟入库 / 重试未入账明细</el-button><el-button type="text" @click="$emit('show','ticket',selected)">打开原入库执行单</el-button></div><receipt-batches :key="selected.id" :ticket-id="Number(selected.id)" :real="selected.actualWarehouse===1" @interaction="showInteraction"/></template><el-empty v-else description="本批尚未审核生成入库执行单" :image-size="60"/></el-tab-pane>
    <el-tab-pane label="收货差异" name="differences" lazy><purchase-difference-panel :key="kind+document.id" :kind="kind" :id="Number(document.id)" :initial-id="initialDifferenceId" @changed="$emit('refresh')" @interaction="openInteraction"/></el-tab-pane>
    <el-tab-pane label="仓库交互" name="logs" lazy><div class="toolbar"><span>实际入库单</span><el-select v-model="selectedId" size="small"><el-option v-for="t in document.tickets" :key="t.id" :value="Number(t.id)" :label="t.sn"/></el-select></div><warehouse-interactions v-if="selected&&selected.actualWarehouse===1&&tab==='logs'" ref="logs" :sn="selected.sn"/><el-empty v-else-if="!selected||selected.actualWarehouse!==1" description="尚无真实仓库交互，虚拟入库可在实收与入账页查看结果" :image-size="60"/></el-tab-pane>
    <el-tab-pane v-if="kind==='purchase'&&canReturns" label="采购退仓" name="purchaseReturns" lazy><purchase-return-summary :purchase-id="Number(document.id)" :original-lines="document.lines||[]"/></el-tab-pane>
    <el-tab-pane label="处理记录" name="events" lazy><el-timeline><el-timeline-item v-for="e in document.events" :key="e.id" :timestamp="e.createTime">{{ e.action }} · {{ e.operator }}<div class="muted">{{ e.message }}</div></el-timeline-item></el-timeline></el-tab-pane>
  </el-tabs>
</section></template>
<script>
import TicketSummary from './TicketSummary'
import PurchaseReturnSummary from './PurchaseReturnSummary'
import ReceiptBatches from './ReceiptBatches'
import WmsInboundPanel from '../warehouse/WmsInboundPanel'
import WarehouseInteractions from '../order/ReturnInteractionPanel'
import PurchaseDifferencePanel from './PurchaseDifferencePanel'
import WarehouseInteractionCell from './WarehouseInteractionCell'
import { checkPermi } from '@/utils/permission'
export default {components:{PurchaseReturnSummary,TicketSummary,ReceiptBatches,WmsInboundPanel,WarehouseInteractions,PurchaseDifferencePanel,WarehouseInteractionCell},props:{document:{type:Object,required:true},kind:{type:String,required:true},initialTab:{type:String,default:'lines'},initialDifferenceId:{type:[Number,String],default:''}},data:()=>({tab:'lines',selectedId:null,receiptStates:{1:'草稿',2:'待审核',3:'收货或入账中',4:'本批已入账',5:'剩余收货已截停',6:'已取消','-1':'已作废'}}),computed:{canReturns(){return checkPermi(['warehouse:purchaseReturn:query'])},number(){return this.kind==='purchase'?this.document.poSn:this.document.noSn},summary(){return this.document.journey||{}},selected(){return (this.document.tickets||[]).find(t=>Number(t.id)===Number(this.selectedId))},active(){return this.kind==='purchase'?[2,3].includes(this.document.poState):[2,3].includes(this.document.noState)||!!this.document.cutoffState},canRetry(){return checkPermi(['warehouse:tickets:retry'])},metrics(){return [{key:'planned',label:this.kind==='purchase'?'采购计划':'本批安排'},...(this.kind==='purchase'?[{key:'scheduled',label:'已安排 / 已入账占用'},{key:'unarranged',label:'可重新安排'}]:[]),{key:'confirmed',label:'仓库已确认实收'},{key:'posted',label:'库存已入账'},{key:'unposted',label:'实收待入账'},{key:'bad',label:'实收次品'},{key:'short',label:'最终短收'}]},notice(){if(this.document.cutoffState)return '当前有截单处理记录，请分别核对仓库结果、已确认实收和库存入账；已发生的实收与入账保留。';if(this.kind==='purchase'&&this.document.poState===1)return '完善商品与价格后审核采购，再按剩余数量分批安排到货。';if(this.kind==='receipt'&&this.document.noState===2)return this.document.actualWarehouse===2?'审核本批到货后按计划自动虚拟收货及入账；可在实收与入账页核对结果。':'审核本批到货后自动下发仓库，等待真实收货回传并入账。';if(this.summary.unposted)return '已有实收尚未全部入账，请在实收与入账页核对失败数量及原因。';if(this.summary.short)return '仓库已最终确认短收。已实收部分入账后，可在收货差异中按当前差额补建到货。';return this.kind==='purchase'?(this.document.stateNotice||'按关联批次跟踪实际收货和库存入账。'):'本批仓库受理、分批实收和库存入账分别核对；仓库接单不代表已入库。'}},watch:{document:{immediate:true,handler(d){if(!(d.tickets||[]).some(t=>Number(t.id)===Number(this.selectedId)))this.selectedId=d.tickets&&d.tickets.length?Number(d.tickets[0].id):null;this.tab=this.initialDifferenceId?'differences':this.initialTab}},initialTab(v){this.tab=v}},methods:{metricText(key){const parts=(this.summary.units||[]).filter(u=>Number(u[key])>0).map(u=>u[key]+' '+u.unit);return parts.join(' + ')||'0'},can(action){return checkPermi(['warehouse:poInfo:'+action])},money(v){return Number(v||0).toFixed(2)},date(v){return v?String(v).replace('T',' ').slice(0,19):'未设置'},selectWarehouse(row){this.selectedId=Number(row.id);this.tab='logs'},async showInteraction(id){this.tab='logs';await this.$nextTick();if(this.$refs.logs)this.$refs.logs.show(id)},async openInteraction(sn,id){const t=(this.document.tickets||[]).find(t=>t.sn===sn);if(t){this.selectedId=Number(t.id);await this.showInteraction(id)}}}}
</script>
<style scoped>.procurement-detail{color:#34445b}header,.toolbar,.actions{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}header h2{font-size:19px;margin:0 0 9px}.code{font-size:13px;overflow-wrap:anywhere}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}.metrics article{padding:17px;border:1px solid #e2eaf4;border-radius:7px;background:#f5f8fd}.metrics span{display:block;font-size:12px;color:#7a899d}.metrics strong{display:block;font-size:25px;margin-top:8px}.metrics small{font-size:12px;font-weight:400}.muted{color:#7a899d;font-size:12px;line-height:1.8;overflow-wrap:anywhere}.warning{color:#b77d19;font-size:12px}.actions{justify-content:flex-start;margin:18px 0}.actions .el-button{margin:0}.toolbar{justify-content:flex-start;margin:16px 0}.toolbar .el-select{min-width:400px}.el-timeline{padding:20px}.procurement-detail ::v-deep td{vertical-align:top}.procurement-detail ::v-deep .cell{overflow-wrap:anywhere}@media(max-width:900px){.metrics{grid-template-columns:1fr 1fr}.toolbar .el-select{min-width:200px}}</style>
